`timescale 1ns / 100ps

// The lane's coefficient memory, host-writable: COEF_WORDS coefficient words, per tier four descriptors (piece bounds, base, degree and
// the rest as data), and in builds with the float tail its fp32 sets. Reset loads the build-time default below, the format's, fitted by
// fit_poly_coeffs.py. A write takes 32 bits at a 9-bit word address (gpnae_pkg's map); the barrel MAC reads one word a cycle, registered;
// the descriptors and tail set of the selected tier are combinational.
module gpnae_coef_mem
  import gpnae_pkg::*;
(
    input logic clk_i,
    input logic rstn_i,

    input logic                   wr_i,  // the load path: one word per cycle
    input logic [LOAD_ADDR_W-1:0] waddr_i,
    input logic [           31:0] wdata_i,

    input  logic [COEF_ADDR_W-1:0] raddr_i,
    output logic [      ACT_W-1:0] rdata_o,  // the word at raddr_i, a cycle later

    input  logic [1:0] tier_i,
    output desc_t      desc_o[NUM_DESC],  // tier_i's descriptors
    output tail_t      tail_o              // tier_i's tail set (zeros without the float tail)
);
  // ── reset default: generated by fit_poly_coeffs.py from gpnae_coef_default.json; do not edit by hand ──
`ifdef FMT_INT8
  localparam logic [128*16-1:0] DEF_WORDS = 2048';
  localparam logic [216*32-1:0] DEF_FIELDS = 6912';  // field word a at [(a - 128)*32 +: 32]
`elsif FMT_BF16
  localparam logic [128*16-1:0] DEF_WORDS = 2048';
  localparam logic [216*32-1:0] DEF_FIELDS = 6912';  // field word a at [(a - 128)*32 +: 32]
`else
  localparam logic [128*32-1:0] DEF_WORDS = 4096';
  localparam logic [216*32-1:0] DEF_FIELDS = 6912';  // field word a at [(a - 128)*32 +: 32]
`endif
  // ── end of the generated reset default ──

  if ($bits(DEF_WORDS) != COEF_WORDS * ACT_W || $bits(DEF_FIELDS) != N_FIELDS * 32) begin : G_BAD_DEFAULT
    $fatal(1, "gpnae_coef_mem: the default tables are %0d and %0d bits, the layout needs %0d and %0d", $bits(DEF_WORDS), $bits(DEF_FIELDS),
           COEF_WORDS * ACT_W, N_FIELDS * 32);
  end

  // The descriptors and tail sets the default's field words decode to, through the load path's own decode.
  function automatic desc_t def_desc(input int t, input int d);
    desc_t r = '0;
    for (int j = 0; j < DESC_STRIDE; j++) r = desc_field(r, j, DEF_FIELDS[((t * NUM_DESC + d) * DESC_STRIDE + j)*32+:32]);
    return r;
  endfunction
  function automatic tail_t def_tail(input int t);
    tail_t r = '0;
    for (int j = 0; j < TAIL_STRIDE; j++) r = tail_field(r, j, DEF_FIELDS[(A_TAIL - A_DESC + t * TAIL_STRIDE + j)*32+:32]);
    return r;
  endfunction

  logic [ACT_W-1:0] words[COEF_WORDS];
  desc_t            desc [NUM_TIERS][NUM_DESC];

  // Which field a write hits.
  logic             w_coef, w_desc, w_tail;
  logic [      3:0] w_di;  // tier * NUM_DESC + descriptor
  logic [      3:0] w_j;
  logic [      1:0] w_t;
  logic [      2:0] w_tj;
  localparam int FA_W = $clog2(N_FIELDS + 1);
  logic [FA_W-1:0] fa;
  assign fa     = FA_W'(waddr_i - LOAD_ADDR_W'(A_DESC));
  assign w_coef = wr_i && (int'(waddr_i) < A_DESC);
  assign w_desc = wr_i && (int'(waddr_i) >= A_DESC) && (int'(waddr_i) < A_TAIL);
  assign w_tail = wr_i && (int'(waddr_i) >= A_TAIL) && (int'(waddr_i) < A_TAIL + NUM_TIERS * TAIL_STRIDE);
  assign w_di   = 4'(int'(fa) / DESC_STRIDE);
  assign w_j    = 4'(int'(fa) % DESC_STRIDE);
  assign w_t    = 2'((int'(waddr_i) - A_TAIL) / TAIL_STRIDE);
  assign w_tj   = 3'((int'(waddr_i) - A_TAIL) % TAIL_STRIDE);

  always_ff @(posedge clk_i or negedge rstn_i) begin
    if (!rstn_i) begin
      /* verilator lint_off UNUSEDLOOP */
      for (int i = 0; i < COEF_WORDS; i++) words[i] <= DEF_WORDS[i*ACT_W+:ACT_W];
      for (int t = 0; t < NUM_TIERS; t++) for (int d = 0; d < NUM_DESC; d++) desc[t][d] <= def_desc(t, d);
      /* verilator lint_on UNUSEDLOOP */
    end else begin
      if (w_coef) words[waddr_i[COEF_ADDR_W-1:0]] <= wdata_i[ACT_W-1:0];
      if (w_desc) desc[int'(w_di)/NUM_DESC][int'(w_di)%NUM_DESC] <= desc_field(desc[int'(w_di)/NUM_DESC][int'(w_di)%NUM_DESC], int'(w_j), wdata_i);
    end
  end

  always_ff @(posedge clk_i) rdata_o <= words[raddr_i];

  logic [1:0] tsel;
  assign tsel = (int'(tier_i) < NUM_TIERS) ? tier_i : 2'd0;  // tier 3 does not exist; gpnae flags it
  always_comb for (int d = 0; d < NUM_DESC; d++) desc_o[d] = desc[tsel][d];

  if (sienna_fmt_pkg::HAS_FLOAT_TAIL) begin : G_TAIL
    tail_t tail[NUM_TIERS];
    always_ff @(posedge clk_i or negedge rstn_i)
      if (!rstn_i) for (int t = 0; t < NUM_TIERS; t++) tail[t] <= def_tail(t);
      else if (w_tail) tail[w_t] <= tail_field(tail[w_t], int'(w_tj), wdata_i);
    assign tail_o = tail[tsel];
  end else begin : G_NO_TAIL
    assign tail_o = '0;
    /* verilator lint_off UNUSEDSIGNAL */
    logic unused_tail;
    assign unused_tail = w_tail ^ ^w_t ^ ^w_tj;
    /* verilator lint_on UNUSEDSIGNAL */
  end
endmodule
